import{_ as a,a0 as r,w as d,s,ao as u,I as o,a1 as i,A as e,x as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"如何启动进入 Linux 命令行 | LCTT x X-CMD","titleTemplate":false,"description":"如何启动进入 Linux 命令行 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何启动进入 Linux 命令行 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何启动进入 Linux 命令行 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20180115 How To Boot Into Linux Command Line","title":"如何启动进入 Linux 命令行","tag":"201802","desc":""},"relativePath":"201802/20180115 How To Boot Into Linux Command Line.md","filePath":"[post].md"}'),p={name:"201802/20180115 How To Boot Into Linux Command Line.md"};function m(x,n,g,b,w,f){const l=r("Link");return d(),s("div",null,[n[16]||(n[16]=u('<h1 id="如何启动进入-linux-命令行" tabindex="-1">如何启动进入 Linux 命令行 <a class="header-anchor" href="#如何启动进入-linux-命令行" aria-label="Permalink to “如何启动进入 Linux 命令行”">​</a></h1><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/how-to-boot-into-linux-command-line_orig.jpg" alt=""></p><p>可能有时候你启动 Linux 时需要或者希望不使用 GUI（图形用户界面），也就是没有 X，而是选择命令行。不管是什么原因，幸运的是，直接启动进入 Linux 命令行 非常简单。它需要在其他内核选项之后对引导参数进行简单的更改。此更改将系统引导到指定的运行级别。</p><h3 id="​为什么要这样做" tabindex="-1">​为什么要这样做？ <a class="header-anchor" href="#​为什么要这样做" aria-label="Permalink to “​为什么要这样做？”">​</a></h3><p>如果你的系统由于无效配置或者显示管理器损坏或任何可能导致 GUI 无法正常启动的情况而无法运行 Xorg，那么启动到命令行将允许你通过登录到终端进行故障排除（假设你知道要怎么做），并能做任何你需要做的东西。引导到命令行也是一个很好的熟悉终端的方式，不然，你也可以为了好玩这么做。</p><h3 id="​访问-grub-菜单" tabindex="-1">​访问 GRUB 菜单 <a class="header-anchor" href="#​访问-grub-菜单" aria-label="Permalink to “​访问 GRUB 菜单”">​</a></h3><p>在启动时，你需要访问 GRUB 启动菜单。如果在每次启动计算机时菜单未设置为显示，那么可能需要在系统启动之前按住 <code>SHIFT</code> 键。在菜单中，需要选择 Linux 发行版条目。高亮显示后该条目，按下 <code>e</code> 编辑引导参数。</p>',7)),o("p",null,[i(l,{href:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/gnu-grub_orig.png"},{default:e(()=>[...n[0]||(n[0]=[o("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/gnu-grub_orig.png",alt:"zorin os grub menu"},null,-1)])]),_:1})]),n[17]||(n[17]=o("p",null,"较老的 GRUB 版本遵循类似的机制。启动管理器应提供有关如何编辑启动参数的说明。",-1)),n[18]||(n[18]=o("h3",{id:"​​指定运行级别",tabindex:"-1"},[t("​​指定运行级别 "),o("a",{class:"header-anchor",href:"#​​指定运行级别","aria-label":"Permalink to “​​指定运行级别”"},"​")],-1)),n[19]||(n[19]=o("p",null,[t("​会出现一个编辑器，你将看到 GRUB 会解析给内核的选项。移动到以 "),o("code",null,"linux"),t(" 开头的行（旧的 GRUB 版本可能是 "),o("code",null,"kernel"),t("，选择它并按照说明操作）。这指定了要解析给内核的参数。在该行的末尾（可能会出现跨越多行，具体取决于你的终端分辨率），只需指定要引导的运行级别，即 "),o("code",null,"3"),t("（多用户模式，纯文本）。")],-1)),o("p",null,[i(l,{href:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/runlevel_orig.png"},{default:e(()=>[...n[1]||(n[1]=[o("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/runlevel_orig.png",alt:"customize grub menu"},null,-1)])]),_:1})]),n[20]||(n[20]=o("p",null,[t("按下 "),o("code",null,"Ctrl-X"),t(" 或 "),o("code",null,"F10"),t(" 将使用这些参数启动系统。开机和以前一样。唯一改变的是启动的运行级别。")],-1)),n[21]||(n[21]=o("p",null,"这是启动后的页面：",-1)),o("p",null,[i(l,{href:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/runlevel_1_orig.png"},{default:e(()=>[...n[2]||(n[2]=[o("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/runlevel_1_orig.png",alt:"boot linux in command line"},null,-1)])]),_:1})]),n[22]||(n[22]=u('<h3 id="运行级别" tabindex="-1">运行级别 <a class="header-anchor" href="#运行级别" aria-label="Permalink to “运行级别”">​</a></h3><p>你可以指定不同的运行级别，默认运行级别是 <code>5</code> （多用户图形界面）。<code>1</code> 启动到“单用户”模式，它会启动进入 root shell。<code>3</code> 提供了一个多用户命令行系统。</p><h3 id="从命令行切换" tabindex="-1">从命令行切换 <a class="header-anchor" href="#从命令行切换" aria-label="Permalink to “从命令行切换”">​</a></h3><p>在某个时候，你可能想要运行显示管理器来再次使用 GUI，最快的方法是运行这个：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo init 5</span></span></code></pre></div><p>就这么简单。就我个人而言，我发现命令行比使用 GUI 工具更令人兴奋和上手。不过，这只是我的个人偏好。</p><hr>',7)),o("p",null,[n[4]||(n[4]=t("via: ",-1)),i(l,{href:"http://www.linuxandubuntu.com/home/how-to-boot-into-linux-command-line"},{default:e(()=>[...n[3]||(n[3]=[t("http://www.linuxandubuntu.com/home/how-to-boot-into-linux-command-line",-1)])]),_:1})]),o("p",null,[n[8]||(n[8]=t("作者：",-1)),i(l,{href:"http://www.linuxandubuntu.com"},{default:e(()=>[...n[5]||(n[5]=[t("LinuxAndUbuntu",-1)])]),_:1}),n[9]||(n[9]=t(" 译者：",-1)),i(l,{href:"https://github.com/geekpi"},{default:e(()=>[...n[6]||(n[6]=[t("geekpi",-1)])]),_:1}),n[10]||(n[10]=t(" 校对：",-1)),i(l,{href:"https://github.com/wxy"},{default:e(()=>[...n[7]||(n[7]=[t("wxy",-1)])]),_:1})]),o("p",null,[n[13]||(n[13]=t("本文由 ",-1)),i(l,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...n[11]||(n[11]=[t("LCTT",-1)])]),_:1}),n[14]||(n[14]=t(" 原创编译，",-1)),i(l,{href:"https://linux.cn/"},{default:e(()=>[...n[12]||(n[12]=[t("Linux中国",-1)])]),_:1}),n[15]||(n[15]=t(" 荣誉推出",-1))])])}const C=a(p,[["render",m]]);export{L as __pageData,C as default};
